import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ToastController, LoadingController, AlertController } from '@ionic/angular';
import { UserService } from 'src/app/data/service/user/user.service';
import { UpdateTeacherProfileModel, IUpdateTeacherProfileModel } from '../../../../../data/model/account/TeacherRegisterModel';
import { SharedIonic } from '../../../../../core/common/SharedIonic';
import { GResponse } from '../../../../../core/common/GResponse';
import { Router } from '@angular/router';

@Component({
  selector: 'app-profile-edit',
  templateUrl: './profile-edit.component.html',
  styleUrls: ['./profile-edit.component.scss']
})
export class ProfileEditComponent implements OnInit {

  form: FormGroup;
  user: IUpdateTeacherProfileModel;

  constructor(
    private userService: UserService,
    private fb: FormBuilder,
    private router: Router,
    public toastController: ToastController,
    public loadingController: LoadingController,
    public alertController: AlertController) { }

  ngOnInit(): void {

    this.form = this.fb.group({
      name: ['', [Validators.required, Validators.maxLength(1000)]],
      family: ['', [Validators.required, Validators.maxLength(1000)]],
      resume: ['', [Validators.required, Validators.maxLength(2000)]],
      mainResume: ['', [Validators.required, Validators.maxLength(20000)]],
      site: ['', [Validators.maxLength(1000)]],
      telegram: ['', [Validators.maxLength(1000)]],
      instagram: ['', [Validators.maxLength(1000)]],
      linkedIn: ['', [Validators.maxLength(1000)]],
      whatsApp: ['', [Validators.maxLength(1000)]],
      avatar: ['', [Validators.required, Validators.maxLength(200000)]],
      address: ['', [Validators.required, Validators.maxLength(1000)]],
      nationalCode: ['', [Validators.required, Validators.maxLength(13)]],
      identificationCode: ['', [Validators.required, Validators.maxLength(13)]],
      birthDay: ['1370-01-01', [Validators.required]]
    });
  }

  ionViewWillEnter() {

    this.onGetData();
  }

  onBackClick() {

    this.router.navigateByUrl('/TeacherPanel');
  }

  async presentAlertConfirm() {
    const alert = await this.alertController.create({
      cssClass: 'main-alert',
      header: 'هشدار!',
      message: 'آیا مطمئن هستید؟',
      buttons: [
        {
          text: 'لغو',
          role: 'cancel',
          cssClass: 'secondary',
          handler: () => {
          }
        }, {
          text: 'بله',
          handler: () => {
            this.onUpdate();
          }
        }
      ]
    });

    await alert.present();
  }

  onGetData() {

    SharedIonic.loading(this.loadingController);

    this.userService.GetTeacherProfileEdit().subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          this.user = res.data;
          this.form.setValue({
            name: this.user.name,
            family: this.user.family,
            address: this.user.address,
            resume: this.user.resume,
            avatar: this.user.userAvatarAddress,
            nationalCode: this.user.nationalCode,
            identificationCode: this.user.identificationCode,
            birthDay: this.user.birthDay,
            mainResume: this.user.mainResume,
            telegram: this.user.telegram,
            instagram: this.user.instagram,
            whatsApp: this.user.whatsApp,
            linkedIn: this.user.linkedIn,
            site: this.user.site
          });
        } else {
          SharedIonic.toast(this.toastController, 'کاربر یافت نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }

  onUpdate() {

    if (!this.form.valid) {

      return;
    }

    SharedIonic.loading(this.loadingController);

    this.userService.UpdateTeacherProfileEdit(
      new UpdateTeacherProfileModel(
        this.user.id,
        this.form.value.address,
        this.form.value.resume,
        this.form.value.nationalCode,
        this.form.value.identificationCode,
        this.form.value.birthDay,
        this.form.value.avatar,
        this.form.value.name,
        this.form.value.family,
        this.form.value.mainResume,
        this.form.value.site,
        this.form.value.telegram,
        this.form.value.instagram,
        this.form.value.whatsApp,
        this.form.value.linkedIn
      )
    ).subscribe(
      res => {
        SharedIonic.dismissLoading(this.loadingController);
        if (res.status === GResponse.SuccessStatus) {

          SharedIonic.successToast(this.toastController);
        } else {
          SharedIonic.toast(this.toastController, 'انجام نشد');
        }
      },
      err => {
        SharedIonic.dismissLoading(this.loadingController);
        SharedIonic.toast(this.toastController, 'خطایی رخ داده است');
      }
    );
  }
}
